### 7.5 Production Implementation: Sparse Conditional Constant Propagation (SCCP) Pass

Below is a complete, working C++20 implementation of Wegman & Zadeck's Dual-Worklist Sparse Conditional Constant Propagation pass over an SSA IR.

```cpp
#include <vector>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <queue>
#include <iostream>

struct LatticeVal {
    enum class State { Top, Constant, Bottom } state = State::Top;
    int64_t value = 0;

    static LatticeVal top() { return {State::Top, 0}; }
    static LatticeVal bottom() { return {State::Bottom, 0}; }
    static LatticeVal constant(int64_t v) { return {State::Constant, v}; }

    bool operator==(const LatticeVal& o) const noexcept {
        if (state != o.state) return false;
        return (state == State::Constant) ? (value == o.value) : true;
    }
    bool operator!=(const LatticeVal& o) const noexcept { return !(*this == o); }

    static LatticeVal meet(const LatticeVal& a, const LatticeVal& b) noexcept {
        if (a.state == State::Top) return b;
        if (b.state == State::Top) return a;
        if (a.state == State::Bottom || b.state == State::Bottom) return bottom();
        return (a.value == b.value) ? a : bottom();
    }
};

struct SSAInst {
    enum class Op { Const, Add, Sub, Mul, CmpEq, Phi, Br, CondBr, Ret } op;
    int id;
    int block_id;
    std::string dest;
    int64_t imm = 0;
    std::vector<std::string> srcs;
    std::vector<int> phi_preds; // For Op::Phi
    int target_true = -1;       // For Br / CondBr
    int target_false = -1;      // For CondBr
};

struct SSABlock {
    int id;
    std::vector<SSAInst> insts;
};

class SCCPPass {
    std::vector<SSABlock>& blocks_;
    std::unordered_map<std::string, LatticeVal> values_;
    std::unordered_map<std::string, std::vector<const SSAInst*>> use_chains_;

    struct CFGEdge {
        int from;
        int to;
        bool operator==(const CFGEdge& o) const noexcept {
            return from == o.from && to == o.to;
        }
    };
    struct EdgeHash {
        size_t operator()(const CFGEdge& e) const noexcept {
            return (static_cast<size_t>(e.from) << 32) ^ static_cast<size_t>(e.to);
        }
    };

    std::unordered_set<CFGEdge, EdgeHash> executable_edges_;
    std::unordered_set<int> executable_blocks_;
    std::queue<CFGEdge> cfg_worklist_;
    std::queue<const SSAInst*> ssa_worklist_;

    LatticeVal getVal(const std::string& var) {
        auto it = values_.find(var);
        return (it != values_.end()) ? it->second : LatticeVal::top();
    }

    void updateVal(const std::string& var, LatticeVal new_val) {
        LatticeVal old_val = getVal(var);
        LatticeVal merged = LatticeVal::meet(old_val, new_val);
        if (merged != old_val) {
            values_[var] = merged;
            for (const SSAInst* user : use_chains_[var]) {
                if (executable_blocks_.count(user->block_id)) {
                    ssa_worklist_.push(user);
                }
            }
        }
    }

    void markEdgeExecutable(int from, int to) {
        CFGEdge edge{from, to};
        if (executable_edges_.insert(edge).second) {
            cfg_worklist_.push(edge);
        }
    }

    void evaluateInst(const SSAInst& inst) {
        switch (inst.op) {
            case SSAInst::Op::Const:
                updateVal(inst.dest, LatticeVal::constant(inst.imm));
                break;

            case SSAInst::Op::Phi: {
                LatticeVal acc = LatticeVal::top();
                for (size_t i = 0; i < inst.srcs.size(); ++i) {
                    int pred = inst.phi_preds[i];
                    if (executable_edges_.count({pred, inst.block_id})) {
                        acc = LatticeVal::meet(acc, getVal(inst.srcs[i]));
                    }
                }
                updateVal(inst.dest, acc);
                break;
            }

            case SSAInst::Op::Add:
            case SSAInst::Op::Sub:
            case SSAInst::Op::Mul:
            case SSAInst::Op::CmpEq: {
                LatticeVal lhs = getVal(inst.srcs[0]);
                LatticeVal rhs = getVal(inst.srcs[1]);

                // Short-circuit multiplication by constant 0: 0 * ⊥ = 0!
                if (inst.op == SSAInst::Op::Mul) {
                    if ((lhs.state == LatticeVal::State::Constant && lhs.value == 0) ||
                        (rhs.state == LatticeVal::State::Constant && rhs.value == 0)) {
                        updateVal(inst.dest, LatticeVal::constant(0));
                        break;
                    }
                }

                if (lhs.state == LatticeVal::State::Bottom ||
                    rhs.state == LatticeVal::State::Bottom) {
                    updateVal(inst.dest, LatticeVal::bottom());
                } else if (lhs.state == LatticeVal::State::Constant &&
                           rhs.state == LatticeVal::State::Constant) {
                    int64_t r = 0;
                    if (inst.op == SSAInst::Op::Add) r = lhs.value + rhs.value;
                    else if (inst.op == SSAInst::Op::Sub) r = lhs.value - rhs.value;
                    else if (inst.op == SSAInst::Op::Mul) r = lhs.value * rhs.value;
                    else if (inst.op == SSAInst::Op::CmpEq) r = (lhs.value == rhs.value) ? 1 : 0;
                    updateVal(inst.dest, LatticeVal::constant(r));
                }
                break;
            }

            case SSAInst::Op::Br:
                markEdgeExecutable(inst.block_id, inst.target_true);
                break;

            case SSAInst::Op::CondBr: {
                LatticeVal cond = getVal(inst.srcs[0]);
                if (cond.state == LatticeVal::State::Bottom) {
                    markEdgeExecutable(inst.block_id, inst.target_true);
                    markEdgeExecutable(inst.block_id, inst.target_false);
                } else if (cond.state == LatticeVal::State::Constant) {
                    if (cond.value != 0) {
                        markEdgeExecutable(inst.block_id, inst.target_true);
                    } else {
                        markEdgeExecutable(inst.block_id, inst.target_false);
                    }
                }
                break;
            }

            case SSAInst::Op::Ret:
                break;
        }
    }

public:
    explicit SCCPPass(std::vector<SSABlock>& blocks) : blocks_(blocks) {
        for (const auto& b : blocks_) {
            for (const auto& inst : b.insts) {
                if (!inst.dest.empty()) values_[inst.dest] = LatticeVal::top();
                for (const auto& src : inst.srcs) {
                    use_chains_[src].push_back(&inst);
                }
            }
        }
    }

    void run(int entry_block = 0) {
        // Seed entry with dummy edge (-1 -> entry_block)
        markEdgeExecutable(-1, entry_block);

        while (!cfg_worklist_.empty() || !ssa_worklist_.empty()) {
            while (!cfg_worklist_.empty()) {
                CFGEdge edge = cfg_worklist_.front();
                cfg_worklist_.pop();

                int target = edge.to;
                bool first_visit = executable_blocks_.insert(target).second;

                // Always re-evaluate Phi nodes when a new incoming edge becomes executable
                for (const auto& inst : blocks_[target].insts) {
                    if (inst.op == SSAInst::Op::Phi) {
                        evaluateInst(inst);
                    } else if (first_visit) {
                        evaluateInst(inst);
                    }
                }
            }

            while (!ssa_worklist_.empty()) {
                const SSAInst* inst = ssa_worklist_.front();
                ssa_worklist_.pop();
                if (executable_blocks_.count(inst->block_id)) {
                    evaluateInst(*inst);
                }
            }
        }

        // Rewrite constants and fold constant branches
        for (auto& b : blocks_) {
            if (!executable_blocks_.count(b.id)) continue;
            for (auto& inst : b.insts) {
                if (!inst.dest.empty()) {
                    LatticeVal v = getVal(inst.dest);
                    if (v.state == LatticeVal::State::Constant && inst.op != SSAInst::Op::Const) {
                        inst.op = SSAInst::Op::Const;
                        inst.imm = v.value;
                        inst.srcs.clear();
                        inst.phi_preds.clear();
                    }
                } else if (inst.op == SSAInst::Op::CondBr) {
                    LatticeVal c = getVal(inst.srcs[0]);
                    if (c.state == LatticeVal::State::Constant) {
                        inst.op = SSAInst::Op::Br;
                        inst.target_true = (c.value != 0) ? inst.target_true : inst.target_false;
                        inst.target_false = -1;
                        inst.srcs.clear();
                    }
                }
            }
        }
    }

    const std::unordered_map<std::string, LatticeVal>& getValues() const { return values_; }
    const std::unordered_set<int>& getExecutableBlocks() const { return executable_blocks_; }
};
```

