### 9.2 Production Implementation: Dynamic Programming Tree-Pattern Instruction Selector

Below is a complete, runnable C++20 implementation of a Bottom-Up Dynamic Programming Instruction Selector targeting x86-64 with complex addressing mode folding (`[base + index*scale + disp]`), `lea` arithmetic, and immediate folding.

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <memory>
#include <limits>

struct IRTree {
    enum class Op { Const, VReg, Add, Mul, Load, Store } op;
    int64_t val = 0;       // Value for Const, or VReg ID for VReg
    std::unique_ptr<IRTree> left;
    std::unique_ptr<IRTree> right;

    // DP memoization state at this node
    int min_cost = std::numeric_limits<int>::max() / 2;
    int best_rule = -1;

    static std::unique_ptr<IRTree> makeConst(int64_t c) {
        auto n = std::make_unique<IRTree>(); n->op = Op::Const; n->val = c; return n;
    }
    static std::unique_ptr<IRTree> makeVReg(int id) {
        auto n = std::make_unique<IRTree>(); n->op = Op::VReg; n->val = id; return n;
    }
    static std::unique_ptr<IRTree> makeBin(Op o, std::unique_ptr<IRTree> l, std::unique_ptr<IRTree> r) {
        auto n = std::make_unique<IRTree>(); n->op = o; n->left = std::move(l); n->right = std::move(r); return n;
    }
    static std::unique_ptr<IRTree> makeUnary(Op o, std::unique_ptr<IRTree> l) {
        auto n = std::make_unique<IRTree>(); n->op = o; n->left = std::move(l); return n;
    }
};

struct MachineInst {
    std::string text;
};

class X86InstructionSelector {
    int next_mreg_ = 100;
    std::vector<MachineInst> emitted_;

    std::string allocReg() { return "%v" + std::to_string(next_mreg_++); }

    static bool isScaleConst(const IRTree* n) noexcept {
        return n && n->op == IRTree::Op::Const &&
               (n->val == 1 || n->val == 2 || n->val == 4 || n->val == 8);
    }

    // Rule Catalog:
    // Rule 1: Reg -> VReg(id)                                      (cost 0)
    // Rule 2: Reg -> Const(c)                                      (cost 1: mov r, c)
    // Rule 3: Reg -> Add(r1, Const(c))                             (cost 1: lea r, [r1 + c])
    // Rule 4: Reg -> Add(r1, r2)                                   (cost 1: lea r, [r1 + r2])
    // Rule 5: Reg -> Add(r1, Mul(r2, Const(s))) where s in {1,2,4,8}(cost 1: lea r, [r1 + r2*s])
    // Rule 6: Reg -> Mul(r1, r2)                                   (cost 3: imul r, r1, r2)
    // Rule 7: Reg -> Load(Add(r1, Mul(r2, Const(s))))              (cost 2: mov r, [r1 + r2*s])
    // Rule 8: Reg -> Load(Add(r1, Const(c)))                       (cost 2: mov r, [r1 + c])
    // Rule 9: Reg -> Load(r1)                                      (cost 2: mov r, [r1])

    void labelBottomUp(IRTree* u) {
        if (!u) return;
        labelBottomUp(u->left.get());
        labelBottomUp(u->right.get());

        auto tryRule = [&](int rule_id, int cost) {
            if (cost < u->min_cost) {
                u->min_cost = cost;
                u->best_rule = rule_id;
            }
        };

        switch (u->op) {
            case IRTree::Op::VReg:
                tryRule(1, 0);
                break;

            case IRTree::Op::Const:
                tryRule(2, 1);
                break;

            case IRTree::Op::Add:
                // Rule 4: generic Add(r1, r2)
                tryRule(4, u->left->min_cost + u->right->min_cost + 1);

                // Rule 3: Add(r1, Const(c))
                if (u->right->op == IRTree::Op::Const) {
                    tryRule(3, u->left->min_cost + 1);
                }
                // Rule 5: Add(r1, Mul(r2, Const(s))) -> single LEA!
                if (u->right->op == IRTree::Op::Mul && isScaleConst(u->right->right.get())) {
                    tryRule(5, u->left->min_cost + u->right->left->min_cost + 1);
                }
                break;

            case IRTree::Op::Mul:
                tryRule(6, u->left->min_cost + u->right->min_cost + 3);
                break;

            case IRTree::Op::Load: {
                // Rule 9: generic Load(r1)
                tryRule(9, u->left->min_cost + 2);

                IRTree* addr = u->left.get();
                if (addr->op == IRTree::Op::Add) {
                    // Rule 8: Load(Add(r1, Const(c)))
                    if (addr->right->op == IRTree::Op::Const) {
                        tryRule(8, addr->left->min_cost + 2);
                    }
                    // Rule 7: Load(Add(r1, Mul(r2, Const(s))))
                    if (addr->right->op == IRTree::Op::Mul && isScaleConst(addr->right->right.get())) {
                        tryRule(7, addr->left->min_cost + addr->right->left->min_cost + 2);
                    }
                }
                break;
            }
            default:
                break;
        }
    }

    std::string reduceTopDown(const IRTree* u) {
        switch (u->best_rule) {
            case 1:
                return "%v" + std::to_string(u->val);
            case 2: {
                std::string dst = allocReg();
                emitted_.push_back({"mov " + dst + ", " + std::to_string(u->val)});
                return dst;
            }
            case 3: {
                std::string r1 = reduceTopDown(u->left.get());
                std::string dst = allocReg();
                emitted_.push_back({"lea " + dst + ", [" + r1 + " + " + std::to_string(u->right->val) + "]"});
                return dst;
            }
            case 4: {
                std::string r1 = reduceTopDown(u->left.get());
                std::string r2 = reduceTopDown(u->right.get());
                std::string dst = allocReg();
                emitted_.push_back({"lea " + dst + ", [" + r1 + " + " + r2 + "]"});
                return dst;
            }
            case 5: {
                std::string r1 = reduceTopDown(u->left.get());
                std::string r2 = reduceTopDown(u->right->left.get());
                int64_t scale = u->right->right->val;
                std::string dst = allocReg();
                emitted_.push_back({"lea " + dst + ", [" + r1 + " + " + r2 + "*" + std::to_string(scale) + "]"});
                return dst;
            }
            case 6: {
                std::string r1 = reduceTopDown(u->left.get());
                std::string r2 = reduceTopDown(u->right.get());
                std::string dst = allocReg();
                emitted_.push_back({"mov " + dst + ", " + r1});
                emitted_.push_back({"imul " + dst + ", " + r2});
                return dst;
            }
            case 7: {
                const IRTree* addr = u->left.get();
                std::string base = reduceTopDown(addr->left.get());
                std::string idx = reduceTopDown(addr->right->left.get());
                int64_t scale = addr->right->right->val;
                std::string dst = allocReg();
                emitted_.push_back({"mov " + dst + ", QWORD PTR [" + base + " + " + idx + "*" + std::to_string(scale) + "]"});
                return dst;
            }
            case 8: {
                const IRTree* addr = u->left.get();
                std::string base = reduceTopDown(addr->left.get());
                int64_t disp = addr->right->val;
                std::string dst = allocReg();
                emitted_.push_back({"mov " + dst + ", QWORD PTR [" + base + " + " + std::to_string(disp) + "]"});
                return dst;
            }
            case 9: {
                std::string addr = reduceTopDown(u->left.get());
                std::string dst = allocReg();
                emitted_.push_back({"mov " + dst + ", QWORD PTR [" + addr + "]"});
                return dst;
            }
            default:
                return "%err";
        }
    }

public:
    std::vector<MachineInst> select(IRTree* root) {
        emitted_.clear();
        labelBottomUp(root);
        reduceTopDown(root);
        return emitted_;
    }
};
```

